import{_ as a}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as e,af as d}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"智谱清言 / Z.ai 术语表","description":"不教操作。只解释清言、Z.ai、ChatGLM、Coding Plan 为什么不是同一个东西。","frontmatter":{"title":"智谱清言 / Z.ai 术语表","description":"不教操作。只解释清言、Z.ai、ChatGLM、Coding Plan 为什么不是同一个东西。","domain":"product","tags":["coding-agent"],"role":"glossary"},"headers":[],"relativePath":"zh/products/zhipu-chat/zhipu-chat-glossary.md","filePath":"zh/products/zhipu-chat/zhipu-chat-glossary.md","lastUpdated":1787110548000}'),o={name:"zh/products/zhipu-chat/zhipu-chat-glossary.md"};function n(i,t,l,h,s,g){return e(),r("div",null,[...t[0]||(t[0]=[d('<h1 id="智谱清言-z-ai-术语表" tabindex="-1">智谱清言 / Z.ai 术语表 <a class="header-anchor" href="#智谱清言-z-ai-术语表" aria-label="Permalink to &quot;智谱清言 / Z.ai 术语表&quot;">​</a></h1><p>不教操作。只解释名字为什么打架。选入口看 <a href="./">学习地图</a>。</p><h2 id="都带「智谱-glm-z-ai」的东西" tabindex="-1">都带「智谱 / GLM / Z.ai」的东西 <a class="header-anchor" href="#都带「智谱-glm-z-ai」的东西" aria-label="Permalink to &quot;都带「智谱 / GLM / Z.ai」的东西&quot;">​</a></h2><table tabindex="0"><thead><tr><th>名字</th><th>是什么</th><th>不是什么</th></tr></thead><tbody><tr><td><strong>智谱清言</strong></td><td>国内消费端助手。协议定义：北京智谱华章科技有限公司经营的生成式人工智能产品（<a href="https://chatglm.cn/pay/policy/vipservice" target="_blank" rel="noreferrer">付费协议 §1.1</a>）。入口 <a href="https://chatglm.cn" target="_blank" rel="noreferrer">chatglm.cn</a></td><td>不是 Coding Plan，不是 API 控制台</td></tr><tr><td><strong>Z.ai 对话</strong></td><td>国际消费端助手。<a href="https://chat.z.ai" target="_blank" rel="noreferrer">chat.z.ai</a> title：Advanced AI Chatbot &amp; Agent</td><td>不是 <code>docs.z.ai</code> 里的 SDK 教程</td></tr><tr><td><strong>Z.ai（公司站用法）</strong></td><td>公司站 <a href="https://www.zhipuai.cn/zh" target="_blank" rel="noreferrer">zhipuai.cn</a> 把 Z.ai 既当品牌、又当原生产品之一</td><td>不等于「所有智谱产品都叫 Z.ai」</td></tr><tr><td><strong>ChatGLM</strong></td><td>2023 年发布的对话模型 / 清言商店文案里的旧称（<a href="https://z.ai/company" target="_blank" rel="noreferrer">z.ai/company</a> 时间线；App Store 介绍）</td><td>不是现在要输入的产品 URL</td></tr><tr><td><strong>GLM</strong></td><td>模型家族名。开放平台介绍：General Language Model（<a href="https://docs.bigmodel.cn/cn/guide/start/introduction" target="_blank" rel="noreferrer">docs.bigmodel.cn</a>）</td><td>不是某一个 App</td></tr><tr><td><strong>GLM-5.2</strong></td><td>2026-08-19 清言首页与 Z.ai 页面展示的旗舰模型名；研究页把它同时挂到聊天和 Coding Plan</td><td>不是「聊天里永远只有这一个」</td></tr><tr><td><strong>GLM Coding Plan</strong></td><td>给 Claude Code 等编码工具的订阅（<a href="https://z.ai/subscribe" target="_blank" rel="noreferrer">z.ai/subscribe</a>）</td><td>不是清言网页的安装步骤</td></tr><tr><td><strong>ZCode</strong></td><td>官方代码工具（<a href="https://www.zhipuai.cn/zh/research/161" target="_blank" rel="noreferrer">research/161</a>）</td><td>不是 chat.z.ai 的聊天标签</td></tr><tr><td><strong>AutoGLM</strong></td><td>公司页与 <a href="https://autoglm.zhipuai.cn" target="_blank" rel="noreferrer">autoglm.zhipuai.cn</a> 上的 Agent / 报告助手</td><td>不是清言里某一个 Mode 的别名（官方把它单列成产品）</td></tr><tr><td><strong>AutoClaw</strong></td><td>公司页原生产品；营销文案是本地 OpenClaw 客户端</td><td>不是 AutoGLM 的另一个拼写而已——公司页两者并排</td></tr><tr><td><strong>CodeGeeX</strong></td><td>官方新闻里的智能编程助手</td><td>不是清言</td></tr><tr><td><strong>BigModel</strong></td><td>国内开放平台 <a href="https://bigmodel.cn" target="_blank" rel="noreferrer">bigmodel.cn</a></td><td>不是聊天会员中心</td></tr><tr><td><strong>清影</strong></td><td>付费协议点名的生视频相关权益</td><td>不是独立于清言的本站教程</td></tr></tbody></table><h2 id="两套主体" tabindex="-1">两套主体 <a class="header-anchor" href="#两套主体" aria-label="Permalink to &quot;两套主体&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>清言</th><th>Z.ai</th></tr></thead><tbody><tr><td>产品 URL</td><td>chatglm.cn</td><td>chat.z.ai / z.ai</td></tr><tr><td>协议里的运营方</td><td>北京智谱华章科技有限公司</td><td>JINGSHENG HENGXING TECHNOLOGY PTE.LTD（<a href="https://docs.z.ai/legal-agreement/terms-of-use" target="_blank" rel="noreferrer">Terms</a>）</td></tr><tr><td>官方有没有写「同一登录」</td><td>没有</td><td>没有</td></tr></tbody></table><p>所以：<strong>不要</strong>把清言会员、Z.ai 登录、Coding Plan、开放平台 API Key 画成一口池子。清言协议只保证「清言会员」和「开放平台付费」独立且可叠加（§4.4），没说国际站共用。</p><h2 id="对话里的-agent-不是仓库-agent" tabindex="-1">对话里的 Agent 不是仓库 Agent <a class="header-anchor" href="#对话里的-agent-不是仓库-agent" aria-label="Permalink to &quot;对话里的 Agent 不是仓库 Agent&quot;">​</a></h2><p>清言首页把自己写成 Agent：理解目标、调用工具、把回答变成交付结果。Z.ai description 写 Build websites、write code、long-horizon tasks。</p><p>这仍是<strong>聊天面</strong>：</p><ul><li>没有官方「在仓库里跑清言 CLI」的步骤。</li><li>官方把仓库 / IDE 编码放到 <strong>GLM Coding Plan</strong> 和 <strong>ZCode</strong>（研究页「Agent」小节）。</li><li>对话里生成的页面或代码，不会自动变成你本机的 git commit。</li></ul><p>对位关系：清言 / Z.ai 对话 ≈ Claude.ai；Coding Plan / ZCode ≈ 给别的编码工具供电，<strong>不是</strong>本目录的 Claude Code 教程。</p><h2 id="禁止当事实写" tabindex="-1">禁止当事实写 <a class="header-anchor" href="#禁止当事实写" aria-label="Permalink to &quot;禁止当事实写&quot;">​</a></h2><ul><li>「清言和 chat.z.ai 同一个账号」</li><li>「免费每天 N 次」（三方站常见，官方协议只说看会员页）</li><li>把 App Store 某一天的 ¥ 内购表写成全国统一价</li><li>产品名写成「ChatGLM 网页版安装 Coding Plan」</li><li>用 <code>docs.z.ai</code> 的 API 模型表当清言下拉框</li></ul><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">学习地图</a></li><li><a href="./zhipu-chat.html">教程</a></li><li><a href="./zhipu-chat-cheatsheet.html">速查表</a></li></ul>',16)])])}const m=a(o,[["render",n]]);export{f as __pageData,m as default};
